import { mount, type Component } from 'svelte';
import Console from './cs/Console.svelte';
import Poll from './poll/Poll.svelte';

let site = new Map<string, Component<any>>([
    ["/", Console],
    ["/poll", Poll]
]);

let page = site.get(window.location.pathname) ?? Console;
mount(page, { target: document.getElementById("app")! });
