import { As } from '../misc/as-state'
import { logger } from '../misc/logger';
import { config } from '../misc/config';
import { type PresenceData } from '../misc/ably';

interface MyProfile {
    codename: string;
    alias: string;
    id: string;
    switchTo: string,
    switchTo2: string,
    setAlias(alias: string): void;
    clearAlias(): void;
    getPresenceData(set?: Partial<PresenceData>): PresenceData;
    itsMyId(target: string): boolean;
    plusMinus(): boolean;
}

export const profile: MyProfile = (() => {
    let log = logger.make("cs-profile");

    let makeProfileId = 
        (codename: string) => `${config.deviceId}/${codename}`;

    let state = $state((() => {
        let codename = config.codenames[0];
        let id = makeProfileId(codename);
        let alias = localStorage.getItem(id) || "";
        let switchTo = "";
        let switchTo2 = "";
        log.info(() => ({id, alias, config}));
        return {codename, alias, id, switchTo, switchTo2};
    })());

    function setAlias(alias: string) {
        state.alias = alias;
        localStorage.setItem(state.id, alias);
    }

    function clearAlias() {
        state.alias = "";
        localStorage.removeItem(state.id);
    }

    function getPresenceData(set?: Partial<PresenceData>): PresenceData {
        return {
            deviceId: config.deviceId,
            iAmATeacher: false,
            profiles: [{
                codename: state.codename,
                alias: state.alias,
                id: state.id
            }],
            hostId: 0,
            ...set
        }
    }

    function itsMyId(target: string): boolean {
        if (target === state.id)
            return true;

        for (let codename of config.codenames) {
            let id = makeProfileId(codename);

            if (target === id)
                return true;
        }

        return false;
    }

    let switchCount = 0;

    function plusMinus(): boolean {
        switchCount = ++switchCount % 4;

        switch (switchCount) {
            case 0:
                state.switchTo = "";
                state.switchTo2 = "";
                break;
            case 1:
            case 3:
                state.switchTo = config.codenames[1];
                state.switchTo2 = "";
                break;
            case 2:
                state.switchTo = config.codenames[1];
                state.switchTo2 = config.codenames[2];
                break;
        }

        log.info(() => ({switchCount}));
        return switchCount < 2;
    }

    return As(state, {
        setAlias,
        clearAlias,
        getPresenceData,
        itsMyId,
        plusMinus,
    });
})();