import type Confetti from "./../ui/Confetti.svelte";
import { As } from '../misc/as-state'

type Partial2<T> = {
    [P in keyof T]?:
        T[P] extends object ? Partial2<T[P]> : T[P];
}

interface Ui {
    name: string;
    switchTo: string;
    switchTo2: string;
    group: string;
    lesson: string;
    connected: boolean;
    plusMinus: boolean;
    tag: {
        deviceId: string;
        profile: string;
        version: string;
        codename: string;
        status: string;
        help: string;
    }
    confetti: Confetti | null;
}

interface MyUi extends Ui {
    update(values: Partial2<Ui>): void;
}

export const ui: MyUi = (() => {
    let state: Ui = $state({
        name: "",
        switchTo: "",
        switchTo2: "",
        group: "",
        lesson: "",
        connected: false,
        plusMinus: true,
        tag: {
            deviceId: "",
            profile: "",
            version: "",
            codename: "",
            status: "",
            help: "",
        },
        confetti: null
    });

    function update(values: Partial2<Ui>) {
        Object.assign(state, values);
    }

    return As(state, {
        update
    });
})();