type CachedValue =
    | string
    | number
    | boolean
    | CachedValue[]
    | { [key: string]: CachedValue };

function matchesSchema<T extends CachedValue>(
    value: unknown,
    schema: T
): value is T {
    if (Array.isArray(schema)) {
        if (!Array.isArray(value)) {
            return false;
        }

        return schema.length === 0 || value.every(item => matchesSchema(item, schema[0]));
    }

    if (typeof schema !== "object") {
        return (
            typeof value === typeof schema &&
            (typeof value !== "string" || value.trim() !== "")
        );
    }

    if (typeof value !== "object" || value === null || Array.isArray(value)) {
        return false;
    }

    let object = value as Record<string, unknown>;

    return Object.keys(schema).every(key => {
        let field = object[key];

        return matchesSchema(field, schema[key]);
    });
}

export function getCached<T extends CachedValue>(
    key: string,
    generate: () => T
): T {
    let generated = generate();
    let cached = localStorage.getItem(key);

    if (cached !== null) {
        try {
            let value: unknown = JSON.parse(cached);

            if (matchesSchema(value, generated)) {
                return value;
            }
        } catch {
            // Invalid cache.
        }
    }

    localStorage.setItem(key, JSON.stringify(generated));
    return generated;
}
