<script lang="ts">
    import type { ComponentProps, Snippet } from "svelte";
    
    import { browser } from '../misc/browser';
    import Confetti from "../ui/Confetti.svelte";
    import SvgScene from '../ui/SvgScene.svelte';
    import AsInput from '../ui/AsInput.svelte';
    import SvgText from '../ui/SvgText.svelte';
    import AsButton from '../ui/AsButton.svelte';
    import SvgWifi from '../ui/svg/Wifi.svelte';
    import { SvgYes } from '../ui/svg/Yes.svg.svelte';
    import { SvgNo } from '../ui/svg/No.svg.svelte';
    import { SvgPmButton } from '../ui/svg/PmButton.svg.svelte';

    import { cs } from './cs-main.svelte';
    import { profile } from './cs-profile.svelte'

    type FontFace = ComponentProps<typeof SvgText>["fontFamily"];

    cs.init();
    browser.onBackFromCache(cs.backFromCache);

    let ui = cs.ui;

    let layout = $state({
        sections: [
            { id: "header", h: 30, color: "antiquewhite" },
            { id: "pad",    h: 60, color: "beige" },
            { id: "footer", h: 10, color: "antiquewhite" }
        ],
        areas: [
            { id: "wifi",   l: 90, t: 2,  w: 10, h: 20 },
            { id: "name",   l: 5,  t: 9,  w: 80, h: 30 },
            { id: "switch",   l: 65,  t: 12, w: 25, h: 12 },
            { id: "switch-2", l: 65,  t: 24, w: 25, h: 12 },
            { id: "plus",   l: 90, t: 22, w: 10, h: 20 },
            { id: "group",  l: 40, t: 45, w: 50, h: 20 },
            { id: "lesson", l: 5,  t: 70, w: 85, h: 25 },

            { id: "yes", l: 7,  t: 12, w: 40, h: 30 },
            { id: "no",  l: 52, t: 56, w: 40, h: 30 },

            { id: "device-id",  l: 2,  t: 5,  w: 25, h: 30 },
            { id: "profile",    l: 2,  t: 35, w: 25, h: 30 },
            { id: "version",    l: 2,  t: 65, w: 25, h: 30 },
            { id: "alias",      l: 32, t: 5,  w: 25, h: 30 },
            { id: "status",     l: 32, t: 35, w: 25, h: 30 },
            { id: "help",       l: 32, t: 65, w: 25, h: 30 },
        ],
        svgs: [
            { id: "name", bgColor: "#ffec99", fontScale: 1.1, font: "Nunito" },
            { id: "switch", bgColor: "#ffec99", fontScale: 1.0, font: "Nunito" },
            { id: "switch-2", bgColor: "#ffec99", fontScale: 1.0, font: "Nunito" },
            { id: "group", font: "Nunito" },
            { id: "lesson", font: "Nunito" },
        ]
    });

    function beforeAliasEdit() {
        if (ui.name === profile.codename) {
            ui.name = ""
        }
    }

    function afterAliasEdit() {
        if (ui.name.trim() === "") {
            cs.clearAlias();
            return;
        }
        cs.setAliasOnEdit(ui.name);
    }

    function addProfile() {
        let name = layout.areas.find(a => a.id === "name")!;
        let hasSwitchButtons = cs.addProfile();
        name.w = hasSwitchButtons ? 58 : 80;
    }

    function area(id: string, text: string,
                  fontFamily: FontFace) : ComponentProps<typeof SvgText>
    {
        let svg = layout.svgs.find(it => it.id === id);

        if (!svg)
            return {text, fontFamily};

        return {
            text,
            bgColor: svg.bgColor,
            fontFamily: svg.font as FontFace,
            fontScale: svg.fontScale
        }
    }
</script>

{#snippet wifi(id: string)}
    <div class="svg" {id}>
        <SvgWifi connected={ui.connected}/>
    </div>
{/snippet}

{#snippet asButton(id: string, content: Snippet<[boolean, boolean]>, handler: () => void)}
    {@const disabled = !ui.connected}
    {@const plusMinus = ui.plusMinus}
    <div class="svg" {id}>
        <AsButton clicked={handler} {disabled}>
            {@render content(disabled, plusMinus)}
        </AsButton>
    </div>
{/snippet}

{#snippet text(id: string, str: string, font: FontFace = "Excalifont")}
    <div class="svg" {id}>
        <SvgText {...area(id, str, font)}/>
    </div>
{/snippet}

{#snippet switchTo(id: string, str: string, font: FontFace = "Excalifont")}
    <div class="svg" {id}>
        {#if str}
            <AsButton clicked={() => cs.switchProfile(str)}>
                <SvgText {...area(id, str, font)}/>
            </AsButton>
        {/if}
    </div>
{/snippet}

{#snippet student()}
    {@const id = "name"}
    <div class="svg" {id}>
        <AsInput bind:value={ui.name}
            beforeEdit={beforeAliasEdit}
            afterEdit={afterAliasEdit}
        >
            <SvgText {...area(id, ui.name, "Excalifont")}/>
        </AsInput>
    </div>
{/snippet}

{#snippet tag(id: string, value: string)}
    <!-- svelte-ignore a11y_click_events_have_key_events -->
    <!-- svelte-ignore a11y_no_static_element_interactions -->
    <div class="svg" {id} onclick={() => cs.tagClick(id, value)}>
        <SvgText {...area(id, value, "Nunito")} textColor="gray" borderColor="gray" bgColor="white"/>
    </div>
{/snippet}

<div class="console">
    <SvgScene {layout}>
        <div class="section" id="header">
            {@render wifi("wifi")}
            {@render student()}
            {@render switchTo("switch", ui.switchTo)}
            {@render switchTo("switch-2", ui.switchTo2)}
            {@render asButton("plus", SvgPmButton, addProfile)}
            {@render text("group", ui.group)}
            {@render text("lesson", ui.lesson)}
        </div>

        <div class="section" id="pad">
            <Confetti bind:this={ui.confetti} />
            {@render asButton("yes", SvgYes, cs.yes)}
            {@render asButton("no", SvgNo, cs.no)}
        </div>

        <div class="section" id="footer">
            {@render tag("device-id", ui.tag.deviceId)}
            {@render tag("profile", ui.tag.profile)}
            {@render tag("version", ui.tag.version)}
            {@render tag("alias", ui.tag.codename)}
            {@render tag("status", ui.tag.status)}
            {@render tag("help", ui.tag.status)}
        </div>
    </SvgScene>
</div>

<style>
    .console {
        min-height: 100dvh;
        background-color: pink;
    }

    .section {
        position: relative;
    }

    .svg {
        position: absolute;
        overflow: hidden;
    }
</style>
