<script lang="ts">
    import { browser } from '../misc/browser';
    import { config } from '../misc/config';
    import { type Client } from '../misc/ably';
    import SvgText from "../ui/SvgText.svelte";
    import { poll } from './poll-main.svelte';

    poll.init();
    browser.onBackFromCache(poll.backFromCache);

    let lenta = poll.lenta;

    function client2str(cli: Client) {
        let str = cli.alias || cli.codename;
        return str;
    }
</script>

{#snippet answer(cli: Client)}
    {@const answer = lenta.answers.get(cli.profileId)}
    {#if answer}
        {@const color = answer === 'yes' ? "badge-success" : "badge-error"}
        <div class="badge {color}">{answer}</div>
    {/if}
{/snippet}

{#snippet peers(count: number)}
    {#if count > 1}
        <kbd class="kbd">{count}</kbd>
    {/if}
{/snippet}

{#snippet btnClearCache(cli: Client)}
    {#if config.btnClearCache}
        <button class="btn btn-xs btn-active btn-warning clear-cache"
            onclick={() => poll.clearCache(cli)}
        >
            Clear cache
        </button>
    {/if}
{/snippet}

{#snippet client(cli: Client)}
    <div>
        <div><SvgText text={client2str(cli)} bgColor="#ffec99" /></div>
        <div class="controls">
            <div class="badge badge-xg bg-blue-50">{cli.codename}</div>
            {@render peers(cli.peerCount)}
            {@render answer(cli)}
            {@render btnClearCache(cli)}
        </div>
    </div>
{/snippet}

<div class="grid">
    {#each poll.clients as cli}
        {@render client(cli)}
    {/each}
</div>

<style>
    .grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: 10px;
    }
    .controls {
        display: flex;
        flex-wrap: wrap;
        gap: 10px;
        padding: 0 10px;
    }
    .btn {
        flex: 0 0 80px;
    }
    .clear-cache {
        margin-left: auto;
    }
</style>
