import * as Ably from 'ably'

import { logger } from './logger';
import { safe } from './try-catch-handle'
import { assert } from './assert'
import { config } from './config';

export interface PresenceData {
    deviceId: string;
    iAmATeacher: boolean;
    profiles: {
        codename: string;
        alias: string;
        id: string;
    }[];
    hostId: number;
}

export interface Client {
    deviceId: string;
    codename: string;
    alias: string;
    profileId: string;
    iAmATeacher: boolean;
    peerCount: number;
    hostId: number;
}

type OnPresence = (clients: Client[]) => void;
type OnTeacherIsHere = (here: boolean) => void;

export interface CsProtocol {
    "clear-cache": {
        codename: string;
    },
    "alias-is-edited": {
        profileId: string;
        alias: string;
    },
    "alias-is-cleared": {
        profileId: string;
    },
    "set-profile-alias": {
        profileId: string;
        alias: string;
    },
    "clear-profile-alias": {
        profileId: string;
    },
    "answer": {
        profileId: string;
        value: string;
    }
}

type MsgT = keyof CsProtocol;
type OnMsg<T extends MsgT> = (msg: CsProtocol[T], from: string, target: string) => void;

type TypeAndHandler = {
    [T in MsgT]: [type: T, handler: OnMsg<T>]
}[MsgT];

type ItsMyTarget = (target: string) => boolean;

type StrOrNull = string | null;
type StrsOrNull = string[] | null;
type SomeTargets = string[] | StrOrNull;

interface MyAbly {
    connect(): void;
    enter(data: PresenceData): void;
    trackPresence(act: OnPresence): void;
    trackTeachers(act: OnTeacherIsHere): void;
    subscribe(itsMyTarget: ItsMyTarget, ...pairs: TypeAndHandler[]): void;
    publish<T extends MsgT>(type: T, msg: CsProtocol[T], targets?: SomeTargets, from?: StrOrNull): void;
}

export const ably: MyAbly = (() => {
    let log = logger.make("ably");
    let realtime: Ably.Realtime;
    let channel: Ably.RealtimeChannel;

    function connect() {
        if (realtime) {
            safe(() => realtime.close());
        }

        realtime = new Ably.Realtime({
            key: config.key,
            clientId: config.deviceId
        });

        channel = realtime.channels.get(config.channel);
    }

    async function enter(data: PresenceData) {
        assert(() => channel !== undefined);
        channel.presence.enter(data)
            .catch(e => console.log(e));

        log.trace(() => ["enter", data]);
    }

    async function fetchClients(): Promise<Client[]> {
        assert(() => channel !== undefined);

        let clients = new Map<string, Client>();

        function getOrCreateClient(data: PresenceData, profile: PresenceData["profiles"][0]) {
            let client = clients.get(profile.id);

            if (client)
                return client;

            client = {
                deviceId: data.deviceId,
                codename: profile.codename,
                alias: profile.alias,
                profileId: profile.id,
                iAmATeacher: data.iAmATeacher,
                peerCount: 0,
                hostId: data.hostId
            }

            clients.set(profile.id, client);
            return client;
        }

        let members = await channel.presence.get();

        for (let member of members) {
            let data = member.data as PresenceData;
            for (let profile of data.profiles) {
                let client = getOrCreateClient(data, profile);
                client.peerCount++;
                log.trace(() => ["presence", client]);
            }
        }

        return [...clients.values()];
    }

    async function trackPresence(act: OnPresence) {
        async function fetchAll() {
            let clients = await fetchClients();
            act(clients);
        }

        assert(() => channel !== undefined);
        fetchAll();

        channel.presence.subscribe(_ => {
            fetchAll();
        });
    }

    function trackTeachers(act: OnTeacherIsHere) {
        async function lookForTeacher() {
            let members = await channel.presence.get();
            let found = members.find(member => member.data.iAmATeacher) !== undefined;
            act(found);
        }

        assert(() => channel !== undefined);
        lookForTeacher();

        channel.presence.subscribe(_ => {
            lookForTeacher();
        });
    }

    interface Envelope {
        type: string;
        from: StrOrNull;
        targets: StrsOrNull;
        msg: object;
    } 

    type OnAnyMsg = (msg: object) => void;
    type TypeAndAnyHandler = [type: MsgT, handler: OnAnyMsg];

    async function subscribe(itsMyTarget: ItsMyTarget, ...pairs: TypeAndAnyHandler[]) {
        assert(() => channel !== undefined);

        function handle(env: Envelope, act: OnAnyMsg) {
            if (env.targets === null) {
                act(env.msg);
            } else {
                env.targets.forEach(target => {
                    if (itsMyTarget(target))
                        act(env.msg);
                });
            }
        }

        for (let [type, handler] of pairs) {
            log.info(() => ({type, handler}));
            await channel.subscribe(type, abliMsg => {
                log.info(() => ({method: "got", type, handler, env: abliMsg.data, abliMsg}));
                handle(abliMsg.data, handler);
            });
        };
    }

    async function publish(type: string, msg: object, targets: SomeTargets = null, from: StrOrNull = null) {
        assert(() => channel !== undefined);

        if (targets !== null)
            targets = Array.isArray(targets) ? targets : [targets];

        let env: Envelope = {type, from, targets, msg};

        await channel.publish(type, env)
            .catch(er => console.log(er));

        log.info(() => ({type, msg: env.msg, env}));
    }

    return {
        connect,
        enter,
        trackPresence,
        trackTeachers,
        subscribe,
        publish,
    } as const;
})();