import { VERSION } from '../version';
import { assert } from '../misc/assert'
import { logger } from '../misc/logger'
import { config } from '../misc/config'
import { ably, type CsProtocol } from '../misc/ably';
import { ui } from './cs-ui.svelte'
import { profile } from './cs-profile.svelte'
import { browser } from '../misc/browser';
import { helpers } from '../misc/helpers';

interface MyConsole {
    ui: typeof ui;
    init(): void;
    backFromCache(): void,
    yes(): void,
    no(): void,
    addProfile(): boolean;
    setAliasOnEdit(alias: string): void;
    clearAlias(): void;
    setAliasFromHost(msg: CsProtocol["set-profile-alias"]): void;
    clearAliasFromHost(msg: CsProtocol["clear-profile-alias"]): void;
    clearCache(): void;
    teacherIsHere(here: boolean): void;
    switchProfile(codename: string): void;
    tagClick(id: string, value: string): void;
}

export const cs: MyConsole = (() => {
    let log = logger.make("cs-main");

    function setPresence() {
        ably.enter(profile.getPresenceData({
            iAmATeacher: false,
            hostId: 0
        }));
    }

    function ably_reconnect() {
        log.info(() => "connecting to ably...");

        ably.connect();
        setPresence();

        ably.trackTeachers(teacherIsHere);

        ably.subscribe(target => profile.itsMyId(target),
            ["clear-cache", clearCache],
            ["set-profile-alias", setAliasFromHost],
            ["clear-profile-alias", clearAliasFromHost],
        );
    }

    function init() {
        let name = profile.alias || profile.codename;
        ui.update({
            name,
            switchTo: profile.switchTo,
            switchTo2: profile.switchTo2,
            group: "2-19",
            lesson: "SQL introduction",
            tag: {
                deviceId: config.deviceId,
                profile: profile.id,
                version: VERSION,
                codename: profile.codename,
                status: "n/a",
                help: "n/a"
            }
        });

        ably_reconnect();
    }

    function backFromCache() {
        ably_reconnect();
    }

    function yes() {
        ably.publish("answer", {
            profileId: profile.id,
            value: "yes"
        })
//        ui.confetti?.launch();
    }

    function no() {
        ably.publish("answer", {
            profileId: profile.id,
            value: "no"
        })
    }

    function addProfile(): boolean {
        ui.plusMinus = profile.plusMinus();
        ui.switchTo = profile.switchTo;
        ui.switchTo2 = profile.switchTo2;

        return ui.switchTo !== "" || ui.switchTo2 !== "";
    }

    function setAliasOnEdit(alias: string) {
        log.info(() => alias);

        ui.name = alias;
        profile.setAlias(alias);

        ably.publish("alias-is-edited", {
            profileId: profile.id,
            alias
        });
    }

    function clearAlias() {
        log.info(() => "no-alias");

        ui.name = profile.codename;
        profile.clearAlias();

        ably.publish("alias-is-cleared", {
            profileId: profile.id
        })
    }

    function setAliasFromHost(msg: CsProtocol["set-profile-alias"]) {
        if (msg.profileId !== profile.id)
            return;

        log.info(() => msg);

        ui.name = msg.alias;
        profile.setAlias(msg.alias);

        setPresence();
    }

    function clearAliasFromHost(msg: CsProtocol["clear-profile-alias"]) {
        if (msg.profileId !== profile.id)
            return;

        log.info(() => msg);

        ui.name = profile.codename;
        profile.clearAlias();

        setPresence();
    }

    function clearCache() {
        log.info(() => profile.id);

        config.clearLocals();
        location.reload();
    }

    function teacherIsHere(here: boolean) {
        ui.connected = here;
    }

    function switchProfile(codename: string) {
        log.info(() => codename);
    }

    function tagClick(id: string, value: string) {
        log.info(() => ({id, value}));
        browser.copyToClipboard(value);
    }

    return {
        ui,
        backFromCache,
        init,
        yes,
        no,
        addProfile,
        setAliasOnEdit,
        clearAlias,
        setAliasFromHost,
        clearAliasFromHost,
        clearCache,
        teacherIsHere,
        switchProfile,
        tagClick,
    }
})();
