export const try_ = (() => {
    type OnError = (er: any) => void;

    function catch_handle<R>(act: () => R, onError?: OnError) {
        try {
            return act();
        } catch (er) {
            if (onError)
                onError(er);
            else
                console.log(er);
        }
    }

    return {
        catch_handle
    } as const;
})();

export function safe<R>(act: () => R) {
    return try_.catch_handle(act);
}